import React, { useState } from "react";

const productsData = [
  { id: 1, name: "Mouse", price: 500 },
  { id: 2, name: "Keyboard", price: 1500 },
  { id: 3, name: "Laptop", price: 60000 }
];

function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);

  const addToCart = (product) => {
    const exists = cart.find((item) => item.id === product.id);
    if (exists) {
      setCart(
        cart.map((item) =>
          item.id === product.id ? { ...item, qty: item.qty + 1 } : item
        )
      );
    } else {
      setCart([...cart, { ...product, qty: 1 }]);
    }
  };

  const addToWishlist = (product) => {
    if (!wishlist.find((item) => item.id === product.id)) {
      setWishlist([...wishlist, product]);
    }
  };

  const totalPrice = cart.reduce((total, item) => total + item.price * item.qty, 0);
  const discount = totalPrice > 5000 ? totalPrice * 0.1 : 0; // 10% discount if total > 5000
  const vat = (totalPrice - discount) * 0.13; // 13% VAT
  const finalAmount = totalPrice - discount + vat;

  return (
    <div style={{ padding: 20, fontFamily: "Arial" }}>
      <h1>Simple React E-Commerce</h1>

      <h2>Products</h2>
      {productsData.map((product) => (
        <div key={product.id}>
          {product.name} - Rs {product.price}
          <button onClick={() => addToCart(product)}>Add to Cart</button>
          <button onClick={() => addToWishlist(product)}>Wishlist</button>
        </div>
      ))}

      <h2>Wishlist</h2>
      {wishlist.length === 0 && <p>No items in wishlist</p>}
      {wishlist.map((item) => (
        <p key={item.id}>{item.name}</p>
      ))}

      <h2>Cart</h2>
      {cart.length === 0 && <p>No products added</p>}
      {cart.map((item) => (
        <p key={item.id}>
          {item.name} - Rs {item.price} x {item.qty}
        </p>
      ))}

      <h2>Checkout</h2>
      <p>Total: Rs {totalPrice}</p>
      <p>Discount: Rs {discount}</p>
      <p>VAT (13%): Rs {vat.toFixed(2)}</p>
      <h3>Final Amount: Rs {finalAmount.toFixed(2)}</h3>
    </div>
  );
}

export default App;
